class Weights(TypedDict):
    qkv_gate: torch.Tensor            # bfloat16 [2304, 8192]: q 16x64, k 2x64, v 2x64, output gate 16x64
    o: torch.Tensor                   # bfloat16 [8192, 1024]
    attn_residual_gate: torch.Tensor  # bfloat16 [8192], the post-attention residual gate's weight
    pre_ffn_norm: torch.Tensor        # bfloat16 [8192] (applied as 1 + w)
    router: torch.Tensor              # float32 [256, 8192]
    router_bias: torch.Tensor         # float32 [256], added to the scores only to choose experts
    pooler: torch.Tensor              # bfloat16 [4096, 8192]
    pre_expert_norm: torch.Tensor     # bfloat16 [4096] (applied as 1 + w)
    w13: torch.Tensor                 # uint8 [32, 8192, 2048]: this GPU's experts, gate then up rows, packed E2M1
    w13_sf: torch.Tensor              # float8_e4m3fn [32, 8192, 256]
    w13_gs: torch.Tensor              # float32 [32]
    w2: torch.Tensor                  # uint8 [32, 4096, 2048]
    w2_sf: torch.Tensor               # float8_e4m3fn [32, 4096, 256]
    w2_gs: torch.Tensor               # float32 [32]
    post_expert_norm: torch.Tensor    # bfloat16 [4096] (applied as 1 + w, before normalizing)
    unpooler: torch.Tensor            # bfloat16 [8192, 4096]; up to 8 tokens only rows 0-1023 (this GPU's slice)
    post_ffn_norm: torch.Tensor       # bfloat16 [8192] (applied as 1 + w, before normalizing)
    ffn_residual_gate: torch.Tensor   # bfloat16 [8192]
    next_pre_attn_norm: torch.Tensor  # bfloat16 [8192], the next layer's input norm (applied as 1 + w)


class Config(TypedDict):
    batch: int            # B sequences
    q_len: int            # L: 1 for decode, 8 for a verify block (causal inside it); 200-16384 on muse_prefill_layer
    tokens: int           # T = B * L, request-major
    hidden: int           # 8192
    num_q_heads: int      # 16 per GPU under TP8
    num_kv_heads: int     # 2
    head_dim: int         # 64
    page_size: int        # 1 in the scored cases (as SGLang serves Muse on H200), 64 in some tests
    window: int           # 2048 on sliding-window layers (a token and the 2,047 before it); 0 = all
    rope_theta: float     # 500000 on sliding-window layers (interleaved RoPE); 0 = no RoPE
    qk_scale_factor: float
    sm_scale: float       # 1/8
    kv_scale: float       # the cache scales' value: 1 in the scored cases (SGLang leaves them unset)
    n_experts: int        # 256
    top_k: int            # 8
    local_experts: int    # 32: this GPU computes experts local_start .. local_start + 31


class Inputs(TypedDict):
    stream: torch.Tensor      # float32 [T, 8192], the residual stream
    attn_input: torch.Tensor  # bfloat16 [T, 8192], the normalized stream (the previous layer's boundary wrote it)
    k_cache: torch.Tensor     # float8_e4m3fn [pages, page_size, 2, 64], written in place
    v_cache: torch.Tensor     # float8_e4m3fn [pages, page_size, 2, 64], written in place
    positions: torch.Tensor   # int64 [T], each new token's position
    cache_loc: torch.Tensor   # int64 [T], each new token's flat cache row
    cache_seqlens: torch.Tensor  # int32 [B], seq_lens + L
    cu_seqlens_q: torch.Tensor   # int32 [B+1], 0, L, 2L, ...
    scheduler_metadata: torch.Tensor | None  # int32, FA3's tile schedule on full-attention decode steps
    k_scale: torch.Tensor     # float32 [], key = e4m3 * k_scale
    v_scale: torch.Tensor     # float32 []
    page_table: torch.Tensor  # int32 [B, max_pages], physical page of each logical page (-1 unused)
    seq_lens: torch.Tensor    # int32 [B], cached tokens per request; the block starts at this position
    local_start: torch.Tensor # int32 [1], this GPU's first expert (a multiple of 32; its weights are w13[0], ...)
    config: Config


HIDDEN = 8192
RMS_EPS = 1e-5
POST_NORM_EPS = 1e-8
FP8 = torch.float8_e4m3fn
N_EXPERTS = 256
TOP_K = 8
LOCAL_EXPERTS = 32
D_EXPERT = 4096
# MuseSpark1xRouter switches to the split BF16 GEMMs above this many tokens.
ROUTER_FP32_MAX_TOKENS = 8
# Up to this many tokens the unpooler runs on this GPU's slice and is all-gathered.
SLICED_UNPOOL_MAX_TOKENS = 8
UNPOOL_SLICE = HIDDEN // 8
# MuseSpark1xFp4Experts' candidates, smallest first.
BLOCK_SIZE_M_CANDIDATES = (8, 16, 32, 48, 64)
ROPE_POSITIONS = 1 << 21
ROPE_THETA = 500_000.0


# ---------------------------------------------------------------------------------------
# SGLang's layer (baseline.py), kept as the fallback for every part.


def _gemm(x, w):
    return _bf16_gemm_dispatch_impl(x, w, None)


def _param(w):
    return nn.Parameter(w.contiguous(), requires_grad=False)


def _norm(cls, w, size, eps, **kw):
    """A Muse norm module holding w (applied as 1 + w), as the checkpoint loads it."""
    norm = cls(size, eps=eps, has_weight=w is not None, zero_centered_gamma=True, **kw)
    if w is not None:
        norm.weight = _param(w)
        norm.precompute_effective_weight()
    return norm


def _residual(w):
    gate = MuseSpark1xNormPreservingResidualConnection(HIDDEN, temperature=0.3)
    gate.gate = _param(w)
    gate.precompute_coefficients()
    return gate


def _marlin_bank(weights):
    """The local experts in Marlin's layout, via SGLang's own loader step."""
    device = weights["w13"].device
    layer = types.SimpleNamespace(
        quant_config=types.SimpleNamespace(group_size=16),
        moe_runner_config=types.SimpleNamespace(is_gated=True),
        intermediate_size_per_partition=weights["w13"].shape[1] // 2,
        params_dtype=torch.bfloat16,
        w13_weight=weights["w13"].contiguous(),
        w2_weight=weights["w2"].contiguous(),
        w13_weight_scale=weights["w13_sf"].contiguous(),
        w2_weight_scale=weights["w2_sf"].contiguous(),
        w13_weight_scale_2=weights["w13_gs"].contiguous(),
        w2_weight_scale_2=weights["w2_gs"].contiguous(),
    )
    prepare_moe_nvfp4_layer_for_marlin(layer)
    expert_map = torch.full((N_EXPERTS,), -1, dtype=torch.int32, device=device)
    expert_map[:LOCAL_EXPERTS] = torch.arange(LOCAL_EXPERTS, dtype=torch.int32, device=device)
    return {
        "w13": layer.w13_weight.data, "w13_s": layer.w13_weight_scale.data, "w13_gs": layer.w13_weight_scale_2.data,
        "w2": layer.w2_weight.data, "w2_s": layer.w2_weight_scale.data, "w2_gs": layer.w2_weight_scale_2.data,
        "expert_map": expert_map, "size_n": layer.intermediate_size_per_partition,
        "workspace": marlin_make_workspace(device, max_blocks_per_sm=4),
    }


def _baseline_prepare(weights):
    device = weights["qkv_gate"].device
    router = weights["router"]
    hi = router.to(torch.bfloat16)
    lo = (router - hi.float()).to(torch.bfloat16)
    # [2^21, 64] float32 cos | sin, as SGLang's RotaryEmbedding builds it.
    inv_freq = 1.0 / (ROPE_THETA ** (torch.arange(0, 64, 2, dtype=torch.float, device=device) / 64))
    freqs = torch.einsum("i,j -> ij", torch.arange(ROPE_POSITIONS, dtype=torch.float, device=device), inv_freq)
    pre_ffn = _norm(MuseSpark1xRMSNorm, weights["pre_ffn_norm"], HIDDEN, RMS_EPS)
    next_pre_attn = _norm(MuseSpark1xRMSNorm, weights["next_pre_attn_norm"], HIDDEN, RMS_EPS)
    post_attn = _norm(MuseSpark1xRMSNorm, None, HIDDEN, POST_NORM_EPS, is_post_norm=True,
                      post_norm_gain_center_type="one", residual_id=1)
    post_ffn = _norm(MuseSpark1xRMSNormWithInputScale, weights["post_ffn_norm"], HIDDEN, POST_NORM_EPS,
                     is_post_norm=True, post_norm_gain_center_type="one", residual_id=2)
    post_expert = _norm(MuseSpark1xRMSNormWithInputScale, weights["post_expert_norm"], D_EXPERT, POST_NORM_EPS,
                        is_post_norm=True, post_norm_gain_center_type="one", residual_id=2)
    state = {
        "dense": {name: weights[name].contiguous() for name in ("qkv_gate", "o", "pooler", "unpooler")},
        "router": router.contiguous(),
        "router_hi_t": hi.t().contiguous(),
        "router_lo_t": lo.t().contiguous(),
        "routing": FusedMuseSparkRouting(expert_bias=weights["router_bias"].float().contiguous(), route_scale=1.0,
                                         router_output_multiplier=0.1767766952966369,
                                         router_score_division_eps=1e-15),
        "cos_sin": torch.cat((freqs.cos(), freqs.sin()), dim=-1),
        "qk_norm": FusedQKNorm(head_dim=64, num_q_heads=16, num_kv_heads=2, eps=RMS_EPS),
        "o_norm_gate": FusedRMSNormGate(MuseSpark1xRMSNorm(64, eps=RMS_EPS, has_weight=False), True, 64),
        "attn_boundary": FusedPostNormResidualPreNorm(post_attn, _residual(weights["attn_residual_gate"]), pre_ffn),
        "ffn_boundary": FusedPostNormResidualPreNorm(post_ffn, _residual(weights["ffn_residual_gate"]), next_pre_attn),
        "pre_expert_norm": _norm(MuseSpark1xRMSNorm, weights["pre_expert_norm"], D_EXPERT, RMS_EPS),
        # MuseSpark1xFp4Experts binds the post-expert norm's effective (1 + w) weight.
        "post_expert_w": post_expert._get_effective_weight().detach().to(torch.bfloat16),
        "bank": _marlin_bank(weights),
        "side_stream": torch.cuda.Stream(device),
        "_modules": (pre_ffn, next_pre_attn, post_attn, post_ffn, post_expert),
    }
    del freqs
    torch.cuda.synchronize()
    return state


def _baseline_experts(x, topk_weights, topk_ids, state):
    """MuseSpark1xFp4Experts._marlin_expert_outputs and its post-expert-norm finalize."""
    bank = state["bank"]
    num_tokens, size_k = x.shape
    size_n = bank["size_n"]
    gemm1_n = 2 * size_n
    local_ids = bank["expert_map"][topk_ids].contiguous()
    topk_weights = topk_weights.to(torch.float32).contiguous()
    for block_size_m in BLOCK_SIZE_M_CANDIDATES:
        if num_tokens * TOP_K / LOCAL_EXPERTS / block_size_m < 0.9:
            break
    sorted_ids, block_experts, n_padded = moe_align_block_size(local_ids, block_size_m, N_EXPERTS)
    cache2 = torch.empty((num_tokens * TOP_K, size_n), device=x.device, dtype=x.dtype)
    cache13 = torch.empty((num_tokens * TOP_K * max(gemm1_n, size_k),), device=x.device, dtype=x.dtype)
    cache1 = cache13[: num_tokens * TOP_K * gemm1_n].view(-1, gemm1_n)
    cache3 = cache13[: num_tokens * TOP_K * size_k].view(-1, size_k)
    common = dict(moe_block_size=block_size_m, mul_topk_weights=False, is_ep=True,
                  b_q_type=scalar_types.float4_e2m1f, is_k_full=True, use_atomic_add=False,
                  use_fp32_reduce=True, is_zp_float=False)
    ws = bank["workspace"]
    cache1 = moe_wna16_marlin_gemm(
        x, cache1, bank["w13"], None, bank["w13_s"], bank["w13_gs"], None, None, None, ws,
        sorted_ids, block_experts, n_padded, topk_weights, top_k=TOP_K,
        size_m=num_tokens, size_n=gemm1_n, size_k=size_k, **common)
    silu_and_mul(cache1.view(-1, gemm1_n), cache2, expert_ids=local_ids.view(-1), expert_step=1)
    y = moe_wna16_marlin_gemm(
        cache2, cache3, bank["w2"], None, bank["w2_s"], bank["w2_gs"], None, None, None, ws,
        sorted_ids, block_experts, n_padded, topk_weights, top_k=1,
        size_m=num_tokens * TOP_K, size_n=size_k, size_k=size_n, **common).view(num_tokens, TOP_K, size_k)
    return fused_post_expert_norm_weighted_sum(
        y, topk_weights, norm_weight=state["post_expert_w"], eps=POST_NORM_EPS, weight_first=True,
        slot_expert_ids=local_ids)


def _baseline_layer(data, state):
    cfg = data["config"]
    batch, length, tokens = cfg["batch"], cfg["q_len"], cfg["tokens"]
    hq, hkv, d = cfg["num_q_heads"], cfg["num_kv_heads"], cfg["head_dim"]
    dense = state["dense"]
    # Attention: MuseSpark1xAttention.forward.
    qkv = _gemm(data["attn_input"], dense["qkv_gate"])
    if cfg["rope_theta"]:
        q, k = state["qk_norm"](qkv, data["positions"], state["cos_sin"])
    else:
        q, k = state["qk_norm"](qkv)
    v = qkv[:, hq * d + hkv * d: hq * d + 2 * hkv * d]
    gate = qkv[:, hq * d + 2 * hkv * d:]
    k_cache, v_cache = data["k_cache"], data["v_cache"]
    scaled = cfg["kv_scale"] != 1.0
    k = k.reshape(tokens, hkv * d)
    if scaled:
        k, v = k / data["k_scale"], v / data["v_scale"]
    # The pool keeps FP8 rows as bytes; slot 0 is a live row here (SGLang reserves it for padding).
    store_cache(k.to(FP8).view(torch.uint8), v.to(FP8).view(torch.uint8),
                k_cache.view(-1, hkv * d).view(torch.uint8), v_cache.view(-1, hkv * d).view(torch.uint8),
                data["cache_loc"], reserved_skip_index=-1)
    window = cfg["window"]
    descale = {}
    if scaled:
        descale = dict(k_descale=data["k_scale"].reshape(1, 1).expand(batch, hkv),
                       v_descale=data["v_scale"].reshape(1, 1).expand(batch, hkv))
    out = flash_attn_with_kvcache(
        q=q.view(tokens, hq, d).to(FP8),
        k_cache=k_cache,
        v_cache=v_cache,
        page_table=data["page_table"],
        cache_seqlens=data["cache_seqlens"],
        cu_seqlens_q=data["cu_seqlens_q"],
        max_seqlen_q=length,
        softmax_scale=cfg["sm_scale"] * cfg["qk_scale_factor"],
        causal=True,
        window_size=(window - 1, 0) if window else (-1, -1),
        scheduler_metadata=data["scheduler_metadata"],
        **descale,
    )
    if isinstance(out, tuple):
        out = out[0]
    o = state["o_norm_gate"](out.reshape(tokens, hq * d).to(torch.bfloat16), gate)
    attn_output = _gemm(o, dense["o"])  # all-reduce: identity

    # Post-attention boundary, router and MoE block: MuseSpark1xMoE._forward_experts.
    split_router = tokens > ROUTER_FP32_MAX_TOKENS
    ffn_input, stream, router_input = state["attn_boundary"](
        data["stream"], attn_output, branch_dtype=torch.bfloat16, router_dtype=None if split_router else torch.float32)
    # The router and routing run on a side stream, overlapping the pooler on the main one.
    main_stream, side_stream = torch.cuda.current_stream(), state["side_stream"]
    side_stream.wait_stream(main_stream)
    expert_input = _gemm(ffn_input, dense["pooler"])
    with torch.cuda.stream(side_stream):
        if split_router:
            logits = torch.mm(ffn_input, state["router_hi_t"], out_dtype=torch.float32)
            logits += torch.mm(ffn_input, state["router_lo_t"], out_dtype=torch.float32)
        else:
            logits = F.linear(router_input, state["router"])
        topk_weights, topk_ids = state["routing"](None, logits, TOP_K, True)
    main_stream.wait_stream(side_stream)
    if not torch.cuda.is_current_stream_capturing():
        for tensor in (topk_weights, topk_ids):
            tensor.record_stream(main_stream)
    # This GPU's experts start at local_start: as SGLang's expert_map on that EP rank.
    local_ids = (topk_ids - data["local_start"]) % N_EXPERTS
    # all-reduce: identity
    expert_output = _baseline_experts(state["pre_expert_norm"](expert_input), topk_weights, local_ids, state)
    if tokens <= SLICED_UNPOOL_MAX_TOKENS:
        unpooled = _gemm(expert_output, dense["unpooler"][:UNPOOL_SLICE])
        ffn_output = F.pad(unpooled, (0, HIDDEN - UNPOOL_SLICE))  # all-gather: identity
    else:
        ffn_output = _gemm(expert_output, dense["unpooler"])

    # Post-FFN boundary, with the next layer's pre-attention norm.
    next_attn_input, stream, _ = state["ffn_boundary"](stream, ffn_output, branch_dtype=torch.bfloat16)
    return next_attn_input, stream, topk_ids


# ---------------------------------------------------------------------------------------
# Dense projections (muse_bf16_proj)

@triton.jit
def _gemm_dot_kernel(x_ptr, w_ptr, w2_ptr, out_ptr, M, N, K, stride_xm, stride_wn, stride_om,
                     SPLIT_K, BM: tl.constexpr, BN: tl.constexpr, BK: tl.constexpr,
                     TWO_W: tl.constexpr, ATOMIC: tl.constexpr):
    """out[M, N] (+)= x[M, K] @ W[N, K].T on tensor cores; W (+ W2 when TWO_W) is BF16."""
    pid_n = tl.program_id(0)
    pid_m = tl.program_id(1)
    pid_k = tl.program_id(2)
    rm = pid_m * BM + tl.arange(0, BM)
    rn = pid_n * BN + tl.arange(0, BN)
    rk = tl.arange(0, BK)
    k_per = K // SPLIT_K
    k0 = pid_k * k_per
    m_mask = rm[:, None] < M
    n_mask = rn[:, None] < N
    x_ptrs = x_ptr + rm[:, None] * stride_xm + (k0 + rk)[None, :]
    w_ptrs = w_ptr + rn[:, None] * stride_wn + (k0 + rk)[None, :]
    w2_ptrs = w2_ptr + rn[:, None] * stride_wn + (k0 + rk)[None, :]
    acc = tl.zeros((BM, BN), dtype=tl.float32)
    for _ in range(0, k_per, BK):
        x = tl.load(x_ptrs, mask=m_mask, other=0.0)
        w = tl.load(w_ptrs, mask=n_mask, other=0.0, eviction_policy="evict_first")
        acc += tl.dot(x, tl.trans(w))
        if TWO_W:
            w2 = tl.load(w2_ptrs, mask=n_mask, other=0.0, eviction_policy="evict_first")
            acc += tl.dot(x, tl.trans(w2))
            w2_ptrs += BK
        x_ptrs += BK
        w_ptrs += BK
    o_ptrs = out_ptr + rm[:, None] * stride_om + rn[None, :]
    o_mask = (rm[:, None] < M) & (rn[None, :] < N)
    if ATOMIC:
        tl.atomic_add(o_ptrs, acc, mask=o_mask, sem="relaxed")
    else:
        tl.store(o_ptrs, acc.to(out_ptr.dtype.element_ty), mask=o_mask)


@triton.jit
def _gemv_fma_kernel(x_ptr, w_ptr, out_ptr, M, N, K, stride_xm, stride_wn, stride_om,
                     SPLIT_K, BM: tl.constexpr, BN: tl.constexpr, BK: tl.constexpr,
                     ATOMIC: tl.constexpr):
    """out[M, N] (+)= x[M, K] @ W[N, K].T on CUDA cores, for a few tokens; W is BF16 or FP32."""
    pid_n = tl.program_id(0)
    pid_m = tl.program_id(1)
    pid_k = tl.program_id(2)
    rm = pid_m * BM + tl.arange(0, BM)
    rn = pid_n * BN + tl.arange(0, BN)
    rk = tl.arange(0, BK)
    k_per = K // SPLIT_K
    k0 = pid_k * k_per
    m_mask = rm[:, None] < M
    n_mask = rn[:, None] < N
    x_ptrs = x_ptr + rm[:, None] * stride_xm + (k0 + rk)[None, :]
    w_ptrs = w_ptr + rn[:, None] * stride_wn + (k0 + rk)[None, :]
    acc = tl.zeros((BM, BN, BK), dtype=tl.float32)
    for _ in range(0, k_per, BK):
        x = tl.load(x_ptrs, mask=m_mask, other=0.0).to(tl.float32)
        w = tl.load(w_ptrs, mask=n_mask, other=0.0, eviction_policy="evict_first").to(tl.float32)
        acc += x[:, None, :] * w[None, :, :]
        x_ptrs += BK
        w_ptrs += BK
    res = tl.sum(acc, axis=2)
    o_ptrs = out_ptr + rm[:, None] * stride_om + rn[None, :]
    o_mask = (rm[:, None] < M) & (rn[None, :] < N)
    if ATOMIC:
        tl.atomic_add(o_ptrs, res, mask=o_mask, sem="relaxed")
    else:
        tl.store(o_ptrs, res.to(out_ptr.dtype.element_ty), mask=o_mask)


def _pow2_at_least(v):
    return 1 << max(0, (v - 1).bit_length())


def _candidates(layer, m, n, k):
    """Launch plans worth timing for m tokens of this layer, cheapest-to-compile first."""
    sms = 132
    cands = []
    seen = set()

    def add(plan):
        kind, bm, bn, bk, split = plan[:5]
        if plan in seen or k % (split * bk) or k // split < bk:
            return
        ctas = triton.cdiv(n, bn) * triton.cdiv(m, bm) * split
        if ctas < sms // 2 or ctas > 64 * sms:
            return
        seen.add(plan)
        cands.append(plan)

    def splits_for(tiles):
        out = []
        for s in (1, 2, 4, 8, 16):
            if tiles * s >= sms:
                out.append(s)
            if tiles * s >= 2 * sms:
                break
        return out or [16]

    if m <= 8:
        bm = _pow2_at_least(m)
        # CUDA-core GEMV: keep BM * BN * BK at 8K fp32 accumulators per 128 threads.
        for bn in (4, 8, 16):
            for bk in (256, 512, 1024):
                if bm * bn * bk > 8192 or bm * bn * bk < 2048:
                    continue
                tiles = triton.cdiv(n, bn)
                for s in splits_for(tiles):
                    add(("fma", bm, bn, bk, s, 4, 2))
    if m >= 2:
        bm = 16 if m <= 16 else (32 if m <= 32 else 64)
        if m >= 128:
            bms = (64, 128)
        else:
            bms = (bm,)
        for bm in bms:
            for bn in ((16, 32, 64) if m <= 32 else (64, 128)):
                for bk in (128, 256):
                    if bm * bk + bn * bk > 64 * 256 + 64 * 256:
                        continue
                    tiles = triton.cdiv(n, bn) * triton.cdiv(m, bm)
                    for s in splits_for(tiles):
                        add(("dot", bm, bn, bk, s, 4, 4 if bk == 128 else 3))
    return cands



# ---------------------------------------------------------------------------------------
# Attention (muse_attention_decode)

LOG2E = 1.4426950408889634
NUM_SMS = 132
_INV_FREQ = {}

def _inv_freq(theta, d, device):
    """RoPE frequencies computed exactly as SGLang's / the reference's (FP32)."""
    key = (theta, d, device)
    t = _INV_FREQ.get(key)
    if t is None:
        if theta:
            t = 1.0 / (theta ** (torch.arange(0, d, 2, dtype=torch.float, device=device) / d))
        else:
            t = torch.zeros(d // 2, dtype=torch.float, device=device)
        _INV_FREQ[key] = t = t.contiguous()
    return t


@triton.jit
def _load_heads(qkv_ptr, inv_freq_ptr, tok0, pos0, col0, rows, QKV_W, eps, factor,
                G: tl.constexpr, NROWS: tl.constexpr, HD: tl.constexpr, ROPE: tl.constexpr, NORM: tl.constexpr):
    """[R, HD] fp32 rows r = j * G + g: head (col0 / HD + g) of token tok0 + j (position pos0 + j),
    RMS-normalized and rotated (interleaved RoPE) when asked. Rows >= NROWS are zero."""
    d = tl.arange(0, HD)
    j = rows // G
    g = rows % G
    rmask = rows < NROWS
    base = qkv_ptr + (tok0 + j)[:, None].to(tl.int64) * QKV_W + col0 + g[:, None] * HD
    x = tl.load(base + d[None, :], mask=rmask[:, None], other=0.0).to(tl.float32)
    if NORM:
        inv = tl.rsqrt(tl.sum(x * x, axis=1) / HD + eps)
        x = x * (inv * factor)[:, None]
    if ROPE:
        # out[2i] = x[2i] cos - x[2i+1] sin, out[2i+1] = x[2i+1] cos + x[2i] sin
        xp = tl.load(base + (d ^ 1)[None, :], mask=rmask[:, None], other=0.0).to(tl.float32)
        if NORM:
            xp = xp * (inv * factor)[:, None]
        freq = tl.load(inv_freq_ptr + d // 2)
        ang = (pos0 + j).to(tl.float32)[:, None] * freq[None, :]
        sign = tl.where(d % 2 == 0, -1.0, 1.0)
        x = x * tl.cos(ang) + sign[None, :] * xp * tl.sin(ang)
    return x


@triton.jit
def _attn_split_kernel(
        qkv_ptr, inv_freq_ptr, seq_lens_ptr, page_table_ptr, cache_loc_ptr, k_cache_ptr, v_cache_ptr,
        k_scale_ptr, v_scale_ptr, out_ptr, ws_acc_ptr, ws_ml_ptr,
        QKV_W, PT_STRIDE, CHUNK, sm_scale_log2, qk_factor, eps,
        HQ: tl.constexpr, HKV: tl.constexpr, HD: tl.constexpr, L: tl.constexpr, G: tl.constexpr,
        R: tl.constexpr, RN: tl.constexpr, PAGE: tl.constexpr, WINDOW: tl.constexpr, ROPE: tl.constexpr,
        SPLITS: tl.constexpr, BLOCK_N: tl.constexpr, DIRECT: tl.constexpr):
    s = tl.program_id(0)
    h = tl.program_id(1)
    b = tl.program_id(2)
    seq = tl.load(seq_lens_ptr + b)
    rows = tl.arange(0, R)
    jrow = rows // G
    qpos = seq + jrow  # each row's query position
    d = tl.arange(0, HD)
    tok0 = b * L

    # Queries: RMSNorm x 5.473 (+ RoPE), rounded to BF16 as the reference does.
    q = _load_heads(qkv_ptr, inv_freq_ptr, tok0, seq, h * G * HD, rows, QKV_W, eps, qk_factor,
                    G, G * L, HD, ROPE, True).to(tl.bfloat16)

    k_scale = tl.load(k_scale_ptr)
    v_scale = tl.load(v_scale_ptr)
    qk_scale = sm_scale_log2 * k_scale  # scores in log2 units

    # This split's share of the cached keys [lo, seq).
    if WINDOW > 0:
        first = tl.maximum(seq - WINDOW + 1, 0)
    else:
        first = seq * 0
    lo = first + s * CHUNK
    hi = tl.minimum(lo + CHUNK, seq)

    m_i = tl.full((R,), float("-inf"), tl.float32)
    l_i = tl.zeros((R,), tl.float32)
    acc = tl.zeros((R, HD), tl.float32)
    offs_n = tl.arange(0, BLOCK_N)
    for start in range(lo, hi, BLOCK_N):
        kpos = start + offs_n
        kmask = kpos < hi
        page = tl.load(page_table_ptr + b.to(tl.int64) * PT_STRIDE + kpos // PAGE, mask=kmask, other=0)
        row = page.to(tl.int64) * PAGE + kpos % PAGE
        kv_off = (row * HKV + h)[:, None] * HD + d[None, :]
        k = tl.load(k_cache_ptr + kv_off, mask=kmask[:, None], other=0.0).to(tl.bfloat16)
        v = tl.load(v_cache_ptr + kv_off, mask=kmask[:, None], other=0.0).to(tl.bfloat16)
        sc = tl.dot(q, tl.trans(k)) * qk_scale
        valid = kmask[None, :]
        if WINDOW > 0:
            valid = valid & (kpos[None, :] > qpos[:, None] - WINDOW)
        sc = tl.where(valid, sc, float("-inf"))
        m_new = tl.maximum(m_i, tl.max(sc, axis=1))
        m_safe = tl.where(m_new == float("-inf"), 0.0, m_new)
        alpha = tl.exp2(m_i - m_safe)
        p = tl.exp2(sc - m_safe[:, None])
        l_i = l_i * alpha + tl.sum(p, axis=1)
        acc = acc * alpha[:, None] + tl.dot(p.to(tl.bfloat16), v)
        m_i = m_new

    if s == SPLITS - 1:
        # The block's own L keys and values: normalized (+ RoPE), FP8 like the cache, stored to
        # their rows, and attended from registers (causal inside the block).
        nrows = tl.arange(0, RN)
        nmask = nrows < L
        kn = _load_heads(qkv_ptr, inv_freq_ptr, tok0, seq, HQ * HD + h * HD, nrows, QKV_W, eps, 1.0,
                         1, L, HD, ROPE, True)
        vn = _load_heads(qkv_ptr, inv_freq_ptr, tok0, seq, (HQ + HKV) * HD + h * HD, nrows, QKV_W, eps, 1.0,
                         1, L, HD, False, False)
        kq = (kn / k_scale).to(k_cache_ptr.dtype.element_ty)
        vq = (vn / v_scale).to(v_cache_ptr.dtype.element_ty)
        loc = tl.load(cache_loc_ptr + tok0 + nrows, mask=nmask, other=0).to(tl.int64)
        new_off = (loc * HKV + h)[:, None] * HD + d[None, :]
        tl.store(k_cache_ptr + new_off, kq, mask=nmask[:, None])
        tl.store(v_cache_ptr + new_off, vq, mask=nmask[:, None])
        k = kq.to(tl.bfloat16)
        v = vq.to(tl.bfloat16)
        sc = tl.dot(q, tl.trans(k)) * qk_scale
        valid = nmask[None, :] & (nrows[None, :] <= jrow[:, None])
        sc = tl.where(valid, sc, float("-inf"))
        m_new = tl.maximum(m_i, tl.max(sc, axis=1))
        m_safe = tl.where(m_new == float("-inf"), 0.0, m_new)
        alpha = tl.exp2(m_i - m_safe)
        p = tl.exp2(sc - m_safe[:, None])
        l_i = l_i * alpha + tl.sum(p, axis=1)
        acc = acc * alpha[:, None] + tl.dot(p.to(tl.bfloat16), v)
        m_i = m_new

    rmask = rows < G * L
    if DIRECT:
        o = acc / tl.where(l_i == 0.0, 1.0, l_i)[:, None] * v_scale
        _norm_gate_store(o, qkv_ptr, out_ptr, tok0, h, rows, rmask, QKV_W, eps, HQ, HKV, HD, G)
    else:
        base = ((b * HKV + h) * SPLITS + s).to(tl.int64) * R
        tl.store(ws_acc_ptr + (base + rows)[:, None] * HD + d[None, :], acc)
        tl.store(ws_ml_ptr + (base + rows) * 2, m_i)
        tl.store(ws_ml_ptr + (base + rows) * 2 + 1, l_i)


@triton.jit
def _norm_gate_store(o, qkv_ptr, out_ptr, tok0, h, rows, rmask, QKV_W, eps,
                     HQ: tl.constexpr, HKV: tl.constexpr, HD: tl.constexpr, G: tl.constexpr):
    """out[token, head] = RMSNorm(o) * sigmoid(gate) for rows r = j * G + g of KV head h."""
    d = tl.arange(0, HD)
    j = rows // G
    head = h * G + rows % G
    inv = tl.rsqrt(tl.sum(o * o, axis=1) / HD + eps)
    tok = (tok0 + j).to(tl.int64)
    gate = tl.load(qkv_ptr + tok[:, None] * QKV_W + (HQ + 2 * HKV) * HD + head[:, None] * HD + d[None, :],
                   mask=rmask[:, None], other=0.0).to(tl.float32)
    y = o * inv[:, None] * tl.sigmoid(gate)
    tl.store(out_ptr + tok[:, None] * (HQ * HD) + head[:, None] * HD + d[None, :], y.to(tl.bfloat16),
             mask=rmask[:, None])


@triton.jit
def _attn_combine_kernel(qkv_ptr, out_ptr, ws_acc_ptr, ws_ml_ptr, v_scale_ptr, QKV_W, eps,
                         HQ: tl.constexpr, HKV: tl.constexpr, HD: tl.constexpr, L: tl.constexpr,
                         G: tl.constexpr, R: tl.constexpr, SPLITS: tl.constexpr):
    h = tl.program_id(0)
    b = tl.program_id(1)
    rows = tl.arange(0, R)
    d = tl.arange(0, HD)
    m_i = tl.full((R,), float("-inf"), tl.float32)
    l_i = tl.zeros((R,), tl.float32)
    acc = tl.zeros((R, HD), tl.float32)
    for s in range(SPLITS):
        base = ((b * HKV + h) * SPLITS + s).to(tl.int64) * R
        m_s = tl.load(ws_ml_ptr + (base + rows) * 2)
        l_s = tl.load(ws_ml_ptr + (base + rows) * 2 + 1)
        a_s = tl.load(ws_acc_ptr + (base + rows)[:, None] * HD + d[None, :])
        m_new = tl.maximum(m_i, m_s)
        m_safe = tl.where(m_new == float("-inf"), 0.0, m_new)
        alpha = tl.exp2(m_i - m_safe)
        beta = tl.exp2(m_s - m_safe)
        l_i = l_i * alpha + l_s * beta
        acc = acc * alpha[:, None] + a_s * beta[:, None]
        m_i = m_new
    o = acc / tl.where(l_i == 0.0, 1.0, l_i)[:, None] * tl.load(v_scale_ptr)
    _norm_gate_store(o, qkv_ptr, out_ptr, b * L, h, rows, rows < G * L, QKV_W, eps, HQ, HKV, HD, G)


def _plan(batch, hkv, span, length):
    """(splits, block_n): enough programs to keep the GPU's memory system busy, with at
    least a few key blocks per split."""
    block_n = 64
    want = 2 * NUM_SMS
    splits = max(1, min(triton.cdiv(want, batch * hkv), triton.cdiv(span, 2 * block_n)))
    return splits, block_n


def _fused_attention(qkv, data, cfg):
    """Attention between the QKV and output projections: qkv [T, (2Hq + 2Hkv) * 64] BF16 (the
    fused projection output, request-major), returns [T, Hq * 64] BF16. Writes the new keys
    and values into data's caches."""
    batch, length = cfg["batch"], cfg["q_len"]
    hq, hkv, hd = cfg["num_q_heads"], cfg["num_kv_heads"], cfg["head_dim"]
    group = hq // hkv
    page = cfg["page_size"]
    window = cfg["window"]
    if not qkv.is_contiguous():
        qkv = qkv.contiguous()
    device = qkv.device
    page_table = data["page_table"]
    capacity = page_table.shape[1] * page
    span = min(window, capacity) if window else capacity
    splits, block_n = _plan(batch, hkv, span, length)
    chunk = triton.cdiv(span, splits)
    chunk = triton.cdiv(chunk, block_n) * block_n
    splits = triton.cdiv(span, chunk)
    rows = max(16, triton.next_power_of_2(group * length))
    rows_new = max(16, triton.next_power_of_2(length))
    out = torch.empty((batch * length, hq * hd), device=device, dtype=torch.bfloat16)
    direct = splits == 1
    if direct:
        ws_acc = ws_ml = out  # unused
    else:
        ws_acc = torch.empty((batch, hkv, splits, rows, hd), device=device, dtype=torch.float32)
        ws_ml = torch.empty((batch, hkv, splits, rows, 2), device=device, dtype=torch.float32)
    rope = bool(cfg["rope_theta"])
    inv_freq = _inv_freq(cfg["rope_theta"], hd, device)
    qkv_w = qkv.shape[-1]
    _attn_split_kernel[(splits, hkv, batch)](
        qkv, inv_freq, data["seq_lens"], page_table, data["cache_loc"], data["k_cache"], data["v_cache"],
        data["k_scale"], data["v_scale"], out, ws_acc, ws_ml,
        qkv_w, page_table.stride(0), chunk, cfg["sm_scale"] * LOG2E, cfg["qk_scale_factor"], RMS_EPS,
        HQ=hq, HKV=hkv, HD=hd, L=length, G=group, R=rows, RN=rows_new, PAGE=page, WINDOW=window, ROPE=rope,
        SPLITS=splits, BLOCK_N=block_n, DIRECT=direct, num_warps=4, num_stages=2)
    if not direct:
        _attn_combine_kernel[(hkv, batch)](
            qkv, out, ws_acc, ws_ml, data["v_scale"], qkv_w, RMS_EPS,
            HQ=hq, HKV=hkv, HD=hd, L=length, G=group, R=rows, SPLITS=splits, num_warps=4)
    return out



# ---------------------------------------------------------------------------------------
# Experts (muse_moe_w4a16)

ALIGN_CHUNK = 256

@triton.jit
def _align_local_kernel(ids_ptr, local_start_ptr, sorted_ptr, block_expert_ptr, n_padded_ptr, local_ids_ptr,
                        P, MAX_BLOCKS, NE: tl.constexpr,
                        E: tl.constexpr, BS: tl.constexpr, BS_P2: tl.constexpr, CHUNK: tl.constexpr,
                        BLOCKS_CHUNK: tl.constexpr):
    """Sort the P = tokens * top_k routes that land on local experts [local_start,
    local_start + E) (mod NE; local_start is read from device memory) into Marlin's layout:
    each expert's routes (in route order) padded to a multiple of BS with the sentinel P;
    block_expert[i] is block i's local expert (-1 past the end); local_ids[p] is route p's
    local expert or -1.

    One program per local expert: each counts every expert's routes (for the padded
    offsets), then places only its own expert's routes, padding and blocks."""
    e = tl.program_id(0)
    experts = tl.arange(0, E)
    offs = tl.arange(0, CHUNK)
    local_start = tl.load(local_start_ptr)
    counts = tl.zeros((E,), tl.int32)
    for c0 in range(0, P, CHUNK):
        p = c0 + offs
        loc = (tl.load(ids_ptr + p, mask=p < P, other=0) - local_start + NE) % NE
        # Non-local routes and the chunk's tail land in bin E, which is dropped.
        loc = tl.where((p < P) & (loc < E), loc, E)
        counts += _bins(loc, E)
    padded = (counts + BS - 1) // BS * BS
    ends = tl.cumsum(padded, axis=0)
    starts = ends - padded
    total = tl.sum(padded, axis=0)
    my_start = tl.sum(tl.where(experts == e, starts, 0), axis=0)
    my_count = tl.sum(tl.where(experts == e, counts, 0), axis=0)
    my_padded = tl.sum(tl.where(experts == e, padded, 0), axis=0)

    running = my_start
    for c0 in range(0, P, CHUNK):
        p = c0 + offs
        in_range = p < P
        loc = (tl.load(ids_ptr + p, mask=in_range, other=0) - local_start + NE) % NE
        mine = (loc == e) & in_range
        rank = tl.cumsum(mine.to(tl.int32), axis=0) - 1
        tl.store(sorted_ptr + running + rank, p, mask=mine)
        running += tl.sum(mine.to(tl.int32), axis=0)
        if e == 0:
            tl.store(local_ids_ptr + p, tl.where(loc < E, loc, -1), mask=in_range)

    # This expert's padding and its blocks' expert ids.
    j = tl.arange(0, BS_P2)
    tl.store(sorted_ptr + my_start + my_count + j, P, mask=j < my_padded - my_count)
    bo = tl.arange(0, BLOCKS_CHUNK)
    for b0 in range(0, my_padded // BS, BLOCKS_CHUNK):
        blk = b0 + bo
        tl.store(block_expert_ptr + my_start // BS + blk, e, mask=blk < my_padded // BS)
    if e == 0:
        tl.store(n_padded_ptr, total)
        # Blocks past the end.
        for b0 in range(0, MAX_BLOCKS, BLOCKS_CHUNK):
            blk = b0 + bo
            tl.store(block_expert_ptr + blk, -1, mask=(blk < MAX_BLOCKS) & (blk * BS >= total))


@triton.jit
def _post_norm_sum_kernel(y_ptr, w_ptr, s_ptr, ids_ptr, out_ptr, eps,
                          TOPK: tl.constexpr, H: tl.constexpr):
    """out[t] = sum over local slots k of s[t, k] * RMSNorm(y[t, k] * w); zero if none."""
    t = tl.program_id(0)
    offs = tl.arange(0, H)
    w = tl.load(w_ptr + offs).to(tl.float32)
    acc = tl.zeros((H,), tl.float32)
    for k in tl.static_range(TOPK):
        live = tl.load(ids_ptr + t * TOPK + k) >= 0
        if live:
            y = tl.load(y_ptr + (t * TOPK + k).to(tl.int64) * H + offs).to(tl.float32) * w
            inv = tl.rsqrt(tl.sum(y * y, axis=0) / H + eps)
            acc += y * (inv * tl.load(s_ptr + t * TOPK + k))
    tl.store(out_ptr + t.to(tl.int64) * H + offs, acc.to(out_ptr.dtype.element_ty))


def _experts(x, bank, state, sorted_ids, block_experts, n_padded, local_ids, topk_weights,
             block_size_m, atomic):
    """The two Marlin GEMMs and the activation between them; returns y [M, top_k, H]."""
    num_tokens, size_k = x.shape
    size_n = bank["size_n"]
    gemm1_n = 2 * size_n
    alloc = torch.zeros if atomic else torch.empty
    cache1 = alloc((num_tokens * TOP_K, gemm1_n), device=x.device, dtype=x.dtype)
    cache2 = torch.empty((num_tokens * TOP_K, size_n), device=x.device, dtype=x.dtype)
    cache3 = alloc((num_tokens * TOP_K, size_k), device=x.device, dtype=x.dtype)
    common = dict(moe_block_size=block_size_m, mul_topk_weights=False, is_ep=True,
                  b_q_type=scalar_types.float4_e2m1f, is_k_full=True, use_atomic_add=atomic,
                  use_fp32_reduce=True, is_zp_float=False)
    ws = state["workspace"]
    cache1 = moe_wna16_marlin_gemm(
        x, cache1, bank["w13"], None, bank["w13_s"], bank["w13_gs"], None, None, None, ws,
        sorted_ids, block_experts, n_padded, topk_weights, top_k=TOP_K,
        size_m=num_tokens, size_n=gemm1_n, size_k=size_k, **common)
    silu_and_mul(cache1.view(-1, gemm1_n), cache2, expert_ids=local_ids.view(-1), expert_step=1)
    y = moe_wna16_marlin_gemm(
        cache2, cache3, bank["w2"], None, bank["w2_s"], bank["w2_gs"], None, None, None, ws,
        sorted_ids, block_experts, n_padded, topk_weights, top_k=1,
        size_m=num_tokens * TOP_K, size_n=size_k, size_k=size_n, **common)
    return y.view(num_tokens, TOP_K, size_k)


def _moe_fast(x, ids, topk_weights, local_start, state, block_size_m, atomic):
    """The local experts' share of the MoE output, [M, H] BF16: x [M, H] BF16, ids [M, 8]
    global expert ids, topk_weights [M, 8] FP32, local_start an int32 [1] device tensor."""
    bank = state["bank"]
    x = x.contiguous()
    num_tokens, hidden = x.shape
    if ids.dtype != torch.int32 or not ids.is_contiguous():
        ids = ids.to(torch.int32).contiguous()
    topk_weights = topk_weights.to(torch.float32).contiguous()
    p = num_tokens * TOP_K
    count = bank["count"]
    max_padded = (p + count * (block_size_m - 1) + 3) // 4 * 4
    max_blocks = triton.cdiv(max_padded, block_size_m)
    sorted_ids = torch.empty((max_padded,), dtype=torch.int32, device=x.device)
    block_experts = torch.empty((max_blocks,), dtype=torch.int32, device=x.device)
    n_padded = torch.empty((1,), dtype=torch.int32, device=x.device)
    local_ids = torch.empty((num_tokens, TOP_K), dtype=torch.int32, device=x.device)
    _align_local_kernel[(count,)](ids, local_start, sorted_ids, block_experts, n_padded, local_ids,
                              p, max_blocks, NE=N_EXPERTS, E=count, BS=block_size_m,
                              BS_P2=triton.next_power_of_2(block_size_m), CHUNK=ALIGN_CHUNK,
                              BLOCKS_CHUNK=min(512, triton.next_power_of_2(max_blocks)), num_warps=4)
    y = _experts(x, bank, state, sorted_ids, block_experts, n_padded, local_ids, topk_weights,
                 block_size_m, atomic)
    out = torch.empty((num_tokens, hidden), dtype=x.dtype, device=x.device)
    _post_norm_sum_kernel[(num_tokens,)](y, state["norm_w"], topk_weights, local_ids, out, POST_NORM_EPS,
                                         TOPK=TOP_K, H=hidden, num_warps=8)
    return out



# ---------------------------------------------------------------------------------------
# The layer with the faster parts


BUCKETS = (1, 8, 16, 32, 128, 256)
BATCH_BUCKETS = (1, 16, 32)
TUNE_BUDGET_S = 230.0


def _bucket(n, buckets=BUCKETS):
    for b in buckets:
        if n <= b:
            return b
    return None


def _run_proj(plan, x, w, n, out=None):
    """x [m, k] @ w[:n].T in BF16 with a tuned plan (not "base"); written into out[:, :n]
    (out may be wider) when given."""
    m, k = x.shape
    _, bm, bn, bk, split, warps, stages = plan
    atomic = split > 1
    if atomic:
        acc = torch.zeros((m, n), device=x.device, dtype=torch.float32)
    elif out is not None:
        acc = out
    else:
        acc = torch.empty((m, n), device=x.device, dtype=torch.bfloat16)
    grid = (triton.cdiv(n, bn), triton.cdiv(m, bm), split)
    if plan[0] == "dot":
        _gemm_dot_kernel[grid](x, w, w, acc, m, n, k, x.stride(0), w.stride(0), acc.stride(0),
                               split, BM=bm, BN=bn, BK=bk, TWO_W=False, ATOMIC=atomic,
                               num_warps=warps, num_stages=stages)
    else:
        _gemv_fma_kernel[grid](x, w, acc, m, n, k, x.stride(0), w.stride(0), acc.stride(0),
                               split, BM=bm, BN=bn, BK=bk, ATOMIC=atomic,
                               num_warps=warps, num_stages=stages)
    if not atomic:
        return acc
    if out is None:
        return acc.to(torch.bfloat16)
    out[:, :n].copy_(acc)
    return out


def _proj_plan(state, name, m):
    return state["proj_plans"].get((name, _bucket(m)), ("base",))


def _proj(state, name, x):
    w = state["dense"][name]
    plan = _proj_plan(state, name, x.shape[0])
    if plan[0] == "base":
        return _gemm(x, w)
    if not x.is_contiguous():
        x = x.contiguous()
    return _run_proj(plan, x, w, w.shape[0])


def _baseline_attention(qkv, data, cfg, state):
    """SGLang's attention between the projections (as in _baseline_layer): [T, Hq * 64] BF16."""
    batch, length, tokens = cfg["batch"], cfg["q_len"], cfg["tokens"]
    hq, hkv, d = cfg["num_q_heads"], cfg["num_kv_heads"], cfg["head_dim"]
    if cfg["rope_theta"]:
        q, k = state["qk_norm"](qkv, data["positions"], state["cos_sin"])
    else:
        q, k = state["qk_norm"](qkv)
    v = qkv[:, hq * d + hkv * d: hq * d + 2 * hkv * d]
    gate = qkv[:, hq * d + 2 * hkv * d:]
    k_cache, v_cache = data["k_cache"], data["v_cache"]
    scaled = cfg["kv_scale"] != 1.0
    k = k.reshape(tokens, hkv * d)
    if scaled:
        k, v = k / data["k_scale"], v / data["v_scale"]
    store_cache(k.to(FP8).view(torch.uint8), v.to(FP8).view(torch.uint8),
                k_cache.view(-1, hkv * d).view(torch.uint8), v_cache.view(-1, hkv * d).view(torch.uint8),
                data["cache_loc"], reserved_skip_index=-1)
    window = cfg["window"]
    descale = {}
    if scaled:
        descale = dict(k_descale=data["k_scale"].reshape(1, 1).expand(batch, hkv),
                       v_descale=data["v_scale"].reshape(1, 1).expand(batch, hkv))
    out = flash_attn_with_kvcache(
        q=q.view(tokens, hq, d).to(FP8), k_cache=k_cache, v_cache=v_cache, page_table=data["page_table"],
        cache_seqlens=data["cache_seqlens"], cu_seqlens_q=data["cu_seqlens_q"], max_seqlen_q=length,
        softmax_scale=cfg["sm_scale"] * cfg["qk_scale_factor"], causal=True,
        window_size=(window - 1, 0) if window else (-1, -1),
        scheduler_metadata=data["scheduler_metadata"], **descale)
    if isinstance(out, tuple):
        out = out[0]
    return state["o_norm_gate"](out.reshape(tokens, hq * d).to(torch.bfloat16), gate)


def _attn_key(cfg):
    return (_bucket(cfg["batch"], BATCH_BUCKETS), cfg["q_len"], bool(cfg["window"]))


def _attention(qkv, data, cfg, state):
    if state["attn_plans"].get(_attn_key(cfg), False):
        return _fused_attention(qkv, data, cfg)
    return _baseline_attention(qkv, data, cfg, state)


def _moe(x, topk_weights, topk_ids, local_start, state):
    plan = state["moe_plans"].get(_bucket(x.shape[0]), ("base",))
    if plan[0] == "base":
        local_ids = (topk_ids - local_start) % N_EXPERTS
        return _baseline_experts(x, topk_weights, local_ids, state)
    return _moe_fast(x, topk_ids, topk_weights, local_start, state["moe"], plan[1], plan[2])


def _layer(data, state):
    cfg = data["config"]
    tokens = cfg["tokens"]
    qkv = _proj(state, "qkv_gate", data["attn_input"])
    o = _attention(qkv, data, cfg, state)
    attn_output = _proj(state, "o", o)  # all-reduce: identity

    split_router = tokens > ROUTER_FP32_MAX_TOKENS
    ffn_input, stream, router_input = state["attn_boundary"](
        data["stream"], attn_output, branch_dtype=torch.bfloat16, router_dtype=None if split_router else torch.float32)
    # The router and routing run on a side stream, overlapping the pooler on the main one.
    main_stream, side_stream = torch.cuda.current_stream(), state["side_stream"]
    side_stream.wait_stream(main_stream)
    expert_input = _proj(state, "pooler", ffn_input)
    with torch.cuda.stream(side_stream):
        if split_router:
            logits = torch.mm(ffn_input, state["router_hi_t"], out_dtype=torch.float32)
            logits += torch.mm(ffn_input, state["router_lo_t"], out_dtype=torch.float32)
        else:
            logits = F.linear(router_input, state["router"])
        topk_weights, topk_ids = state["routing"](None, logits, TOP_K, True)
    main_stream.wait_stream(side_stream)
    if not torch.cuda.is_current_stream_capturing():
        for tensor in (topk_weights, topk_ids):
            tensor.record_stream(main_stream)
    expert_output = _moe(state["pre_expert_norm"](expert_input), topk_weights, topk_ids, data["local_start"], state)

    unpooler = state["dense"]["unpooler"]
    if tokens <= SLICED_UNPOOL_MAX_TOKENS:
        plan = _proj_plan(state, "unpooler", tokens)
        if plan[0] == "base":
            unpooled = _gemm(expert_output, unpooler[:UNPOOL_SLICE])
            ffn_output = F.pad(unpooled, (0, HIDDEN - UNPOOL_SLICE))  # all-gather: identity
        else:
            ffn_output = torch.zeros((tokens, HIDDEN), device=expert_output.device, dtype=torch.bfloat16)
            _run_proj(plan, expert_output.contiguous(), unpooler, UNPOOL_SLICE, out=ffn_output)
    else:
        ffn_output = _proj(state, "unpooler", expert_output)

    next_attn_input, stream, _ = state["ffn_boundary"](stream, ffn_output, branch_dtype=torch.bfloat16)
    return next_attn_input, stream, topk_ids


def kernel_fn(data: Inputs, state):
    return _layer(data, state)


# ---------------------------------------------------------------------------------------
# Tuning (in prepare, untimed)


class _Bench:
    def __init__(self, device):
        # Larger than H200's L2, cleared before each replay as the judge does.
        self.flush = torch.empty(128 * 1024 * 1024 // 4, dtype=torch.int32, device=device)
        self.stream = torch.cuda.Stream(device)

    def time(self, fn, reps=15):
        with torch.cuda.stream(self.stream):
            for _ in range(2):
                fn()
        self.stream.synchronize()
        graph = torch.cuda.CUDAGraph()
        with torch.cuda.graph(graph, stream=self.stream):
            fn()
        starts = [torch.cuda.Event(enable_timing=True) for _ in range(reps)]
        ends = [torch.cuda.Event(enable_timing=True) for _ in range(reps)]
        with torch.cuda.stream(self.stream):
            for i in range(reps):
                self.flush.zero_()
                starts[i].record()
                graph.replay()
                ends[i].record()
        ends[-1].synchronize()
        times = sorted(s.elapsed_time(e) for s, e in zip(starts, ends))
        del graph
        return times[len(times) // 2]


def _rel(a, b):
    return float((a.float() - b.float()).norm() / b.float().norm().clamp(min=1e-12))


def _tune_proj(state, bench, t0):
    gen = torch.Generator(device=bench.flush.device).manual_seed(77)
    for bucket in BUCKETS:
        for name in ("qkv_gate", "o", "pooler", "unpooler"):
            w_full = state["dense"][name]
            n = UNPOOL_SLICE if (name == "unpooler" and bucket <= SLICED_UNPOOL_MAX_TOKENS) else w_full.shape[0]
            k = w_full.shape[1]
            w = w_full[:n]
            x = torch.randn((bucket, k), generator=gen, device=w.device).to(torch.bfloat16)
            xs = torch.randn((max(1, bucket - 3), k), generator=gen, device=w.device).to(torch.bfloat16)
            ref, ref_s = x.double() @ w.double().T, xs.double() @ w.double().T
            base_t = bench.time(lambda: _gemm(x, w))
            best, best_t = ("base",), base_t
            for plan in _candidates(name, bucket, n, k):
                if time.time() - t0 > TUNE_BUDGET_S:
                    break
                try:
                    if _rel(_run_proj(plan, x, w_full, n), ref) > 4e-3:
                        continue
                    if _rel(_run_proj(plan, xs, w_full, n), ref_s) > 4e-3:
                        continue
                    t = bench.time(lambda: _run_proj(plan, x, w_full, n))
                except Exception as e:
                    print(f"skip {name} m{bucket} {plan}: {type(e).__name__}: {str(e)[:100]}")
                    continue
                if t < best_t:
                    best, best_t = plan, t
            if best[0] != "base":
                tb = bench.time(lambda: _gemm(x, w), reps=31)
                tw = bench.time(lambda: _run_proj(best, x, w_full, n), reps=31)
                if tw >= tb:
                    best = ("base",)
                best_t, base_t = min(tw, tb), tb
            state["proj_plans"][(name, bucket)] = best
            print(f"proj {name:9s} m{bucket:<4d}: {best} {best_t * 1e3:.1f} us (sglang {base_t * 1e3:.1f} us)")


def _routing_ids(bs, device, gen):
    scores = torch.rand((bs, N_EXPERTS), generator=gen, device=device)
    z = torch.randn((N_EXPERTS,), generator=gen, device=device)
    u = torch.rand((N_EXPERTS,), generator=gen, device=device).clamp(min=1e-12)
    scores = scores + 0.03 * z / (-u.log()).sqrt()
    routed = scores.topk(TOP_K, dim=-1)
    ids = routed.indices
    pairs = torch.bincount((ids // LOCAL_EXPERTS).flatten(), minlength=N_EXPERTS // LOCAL_EXPERTS)
    ids = (ids - LOCAL_EXPERTS * pairs.argmax()) % N_EXPERTS
    return ids.to(torch.int32), (routed.values / routed.values.sum(-1, keepdim=True)).float()


def _tune_moe(state, bench, t0):
    device = bench.flush.device
    gen = torch.Generator(device=device).manual_seed(78)
    for bucket in BUCKETS:
        # Checked at the bucket's size and a smaller, odd one; experts start at 32 to cover the rotation.
        cases = []
        for bs in (bucket, max(1, bucket - 3)):
            x = torch.randn((bs, D_EXPERT), generator=gen, device=device).to(torch.bfloat16)
            ids, wts = _routing_ids(bs, device, gen)
            ls = torch.tensor([32], dtype=torch.int32, device=device)
            ids = (ids + 32) % N_EXPERTS
            ref = _baseline_experts(x, wts, (ids - ls) % N_EXPERTS, state)
            cases.append((x, ids, wts, ls, ref))
        x, ids, wts, ls, _ = cases[0]
        base_t = bench.time(lambda: _baseline_experts(x, wts, (ids - ls) % N_EXPERTS, state))
        best, best_t = ("base",), base_t
        sglang_bsm = next((b for b in BLOCK_SIZE_M_CANDIDATES if bucket * TOP_K / LOCAL_EXPERTS / b < 0.9),
                          BLOCK_SIZE_M_CANDIDATES[-1])
        for bsm in BLOCK_SIZE_M_CANDIDATES:
            if bsm > 16 and bsm > 2 * sglang_bsm:
                continue
            for atomic in (False, True):
                if time.time() - t0 > TUNE_BUDGET_S:
                    break
                plan = ("fast", bsm, atomic)
                try:
                    if any(_rel(_moe_fast(cx, ci, cw, cl, state["moe"], bsm, atomic), cr) > 1e-2
                           for cx, ci, cw, cl, cr in cases):
                        print(f"moe bs{bucket} {plan}: wrong result, skipped")
                        continue
                    t = bench.time(lambda: _moe_fast(x, ids, wts, ls, state["moe"], bsm, atomic))
                except Exception as e:
                    print(f"moe bs{bucket} {plan}: {type(e).__name__}: {str(e)[:160]}")
                    continue
                if t < best_t:
                    best, best_t = plan, t
        if best[0] != "base":
            tb = bench.time(lambda: _baseline_experts(x, wts, (ids - ls) % N_EXPERTS, state), reps=31)
            tw = bench.time(lambda: _moe_fast(x, ids, wts, ls, state["moe"], best[1], best[2]), reps=31)
            if tw >= tb:
                best = ("base",)
            best_t, base_t = min(tw, tb), tb
        state["moe_plans"][bucket] = best
        print(f"moe bs{bucket:<4d}: {best} {best_t * 1e3:.1f} us (sglang {base_t * 1e3:.1f} us)")


def _attn_inputs(batch, ctx, length, sliding, page, kv_scale, device, gen, random_bytes=False):
    """A step's attention inputs (the layer's fields), with the fused projection output."""
    hq, hkv, d = 16, 2, 64
    seq = (ctx * (1 + 0.075 * (2 * torch.rand((batch,), generator=gen, device=device) - 1))).long().clamp(min=1)
    longest = math.ceil(ctx * 1.075)
    max_pages = (longest + length + page - 1) // page
    total = batch * max_pages
    perm = torch.randperm(total, generator=gen, device=device).to(torch.int32)
    page_table = perm.view(batch, max_pages).contiguous()
    shape = (total, page, hkv, d)
    if random_bytes:
        # E4M3 bytes with bit 6 clear: magnitudes below 2, never NaN.
        k_cache = (torch.randint(0, 256, shape, generator=gen, device=device, dtype=torch.uint8) & 0xBF).view(FP8)
        v_cache = (torch.randint(0, 256, shape, generator=gen, device=device, dtype=torch.uint8) & 0xBF).view(FP8)
    else:
        k_cache = (torch.randn(shape, generator=gen, device=device) / kv_scale).to(FP8)
        v_cache = (torch.randn(shape, generator=gen, device=device) / kv_scale).to(FP8)
    qkv = torch.randn((batch * length, (2 * hq + 2 * hkv) * d), generator=gen, device=device).to(torch.bfloat16)
    positions = (seq[:, None] + torch.arange(length, device=device)).reshape(-1)
    pos = positions.view(batch, length)
    cache_loc = (torch.gather(page_table.long(), 1, pos // page) * page + pos % page).reshape(-1)
    cache_seqlens = (seq + length).to(torch.int32)
    cu_seqlens_q = torch.arange(0, batch * length + 1, length, dtype=torch.int32, device=device)
    meta = None
    if not sliding and length == 1:
        try:
            from sgl_kernel.flash_attn import get_scheduler_metadata
            meta = get_scheduler_metadata(
                batch_size=batch, max_seqlen_q=1, max_seqlen_k=int(cache_seqlens.max()), num_heads=hq,
                num_heads_k=hkv, headdim=d, cache_seqlens=cache_seqlens, qkv_dtype=FP8,
                cu_seqlens_q=cu_seqlens_q, page_size=page, causal=True, num_splits=0)
        except Exception:
            meta = None
    cfg = {"batch": batch, "q_len": length, "tokens": batch * length, "hidden": HIDDEN, "num_q_heads": hq,
           "num_kv_heads": hkv, "head_dim": d, "page_size": page, "window": 2048 if sliding else 0,
           "rope_theta": ROPE_THETA if sliding else 0.0, "qk_scale_factor": 5.4730064863875, "sm_scale": 0.125,
           "kv_scale": kv_scale, "n_experts": N_EXPERTS, "top_k": TOP_K, "local_experts": LOCAL_EXPERTS}
    data = {"positions": positions, "cache_loc": cache_loc, "cache_seqlens": cache_seqlens,
            "cu_seqlens_q": cu_seqlens_q, "scheduler_metadata": meta, "k_cache": k_cache, "v_cache": v_cache,
            "k_scale": torch.tensor(kv_scale, dtype=torch.float32, device=device),
            "v_scale": torch.tensor(kv_scale, dtype=torch.float32, device=device),
            "page_table": page_table, "seq_lens": seq.to(torch.int32), "config": cfg}
    return qkv, data


def _attn_reference(qkv, data, k_new, v_new):
    """FP32 attention with BF16 queries, attending the given new FP8 entries: [T, 1024]."""
    cfg = data["config"]
    batch, length, hq, hkv, d = cfg["batch"], cfg["q_len"], 16, 2, 64
    page, window = cfg["page_size"], cfg["window"]
    ks, vs = float(data["k_scale"]), float(data["v_scale"])
    x = qkv.float().view(batch, length, -1)
    q = x[..., :hq * d].reshape(batch, length, hq, d)
    gate = x[..., (hq + 2 * hkv) * d:]
    q = q * torch.rsqrt(q.pow(2).mean(-1, keepdim=True) + RMS_EPS) * cfg["qk_scale_factor"]
    if cfg["rope_theta"]:
        inv = 1.0 / (cfg["rope_theta"] ** (torch.arange(0, d, 2, device=q.device).float() / d))
        pos = data["seq_lens"].long()[:, None] + torch.arange(length, device=q.device)
        ang = pos.float()[..., None] * inv
        cos, sin = ang.cos().unsqueeze(-2), ang.sin().unsqueeze(-2)
        e, o = q[..., 0::2], q[..., 1::2]
        q = torch.stack([e * cos - o * sin, e * sin + o * cos], -1).flatten(-2)
    q = q.to(torch.bfloat16).float()
    kf = data["k_cache"].view(-1, hkv, d)
    vf = data["v_cache"].view(-1, hkv, d)
    out = torch.empty((batch, length, hq, d), device=q.device)
    for b in range(batch):
        seq = int(data["seq_lens"][b])
        past = torch.arange(seq, device=q.device)
        rows = data["page_table"][b].long()[past // page] * page + past % page
        keys = torch.cat([kf[rows].float(), k_new[b].float()]) * ks
        vals = torch.cat([vf[rows].float(), v_new[b].float()]) * vs
        for j in range(length):
            p = seq + j
            lo = max(0, p - window + 1) if window else 0
            att = torch.einsum("kgd,tkd->kgt", q[b, j].view(hkv, hq // hkv, d), keys[lo:p + 1]) * cfg["sm_scale"]
            out[b, j] = torch.einsum("kgt,tkd->kgd", att.softmax(-1), vals[lo:p + 1]).reshape(hq, d)
    out = out * torch.rsqrt(out.pow(2).mean(-1, keepdim=True) + RMS_EPS)
    return (out.reshape(batch, length, hq * d) * torch.sigmoid(gate)).reshape(batch * length, hq * d)


def _check_attention(device, gen):
    for batch, ctx, length, sliding, page, kv_scale in ((2, 2600, 1, True, 1, 1.0), (2, 900, 8, False, 64, 1.0),
                                                       (3, 2100, 8, True, 64, 1 / 64), (1, 1500, 1, False, 1, 1 / 64)):
        qkv, data = _attn_inputs(batch, ctx, length, sliding, page, kv_scale, device, gen)
        out = _fused_attention(qkv, data, data["config"])
        slots = data["cache_loc"].view(batch, length)
        k_new = data["k_cache"].view(-1, 2, 64)[slots]
        v_new = data["v_cache"].view(-1, 2, 64)[slots]
        ref = _attn_reference(qkv, data, k_new, v_new)
        err = _rel(out, ref)
        # The new values as stored, against the projection's.
        kv_err = _rel(v_new.float() * kv_scale, qkv.float()[:, 18 * 64:20 * 64].reshape(batch, length, 2, 64))
        if err > 1e-2 or kv_err > 8e-2 or not torch.isfinite(out.float()).all():
            print(f"attention check failed: B{batch} ctx{ctx} L{length} sliding={sliding} page{page}"
                  f" kv_scale {kv_scale}: output err {err:.2e}, value err {kv_err:.2e}")
            return False
    return True


def _tune_attention(state, bench, t0):
    device = bench.flush.device
    gen = torch.Generator(device=device).manual_seed(79)
    if not _check_attention(device, gen):
        return
    for batch in BATCH_BUCKETS:
        for length in (1, 8):
            for sliding in (True, False):
                if time.time() - t0 > TUNE_BUDGET_S:
                    return
                qkv, data = _attn_inputs(batch, 80000, length, sliding, 1, 1.0, device, gen, random_bytes=True)
                cfg = data["config"]
                try:
                    tb = bench.time(lambda: _baseline_attention(qkv, data, cfg, state))
                    tw = bench.time(lambda: _fused_attention(qkv, data, cfg))
                except Exception as e:
                    print(f"attention B{batch} L{length}: {type(e).__name__}: {str(e)[:160]}")
                    continue
                state["attn_plans"][_attn_key(cfg)] = tw < tb
                print(f"attention B{batch:<3d} L{length} {'sliding' if sliding else 'full   '}:"
                      f" fused {tw * 1e3:.1f} us, sglang {tb * 1e3:.1f} us")
                del qkv, data


def _layer_inputs(batch, ctx, length, sliding, device, gen):
    qkv, data = _attn_inputs(batch, ctx, length, sliding, 1, 1.0, device, gen)
    tokens = batch * length
    stream = torch.randn((tokens, HIDDEN), generator=gen, device=device) * 0.7
    data["stream"] = stream
    data["attn_input"] = (stream * torch.rsqrt(stream.pow(2).mean(-1, keepdim=True) + RMS_EPS)).to(torch.bfloat16)
    data["local_start"] = torch.tensor([32], dtype=torch.int32, device=device)
    return data


def _check_layer(state, device):
    """The whole layer with the chosen parts against SGLang's on the same inputs.

    Attention runs SGLang's path here: SGLang rounds queries to FP8 and ours keeps BF16, so
    the two differ by about FP8's own error, and routing near-ties then flip. Our attention
    is checked against an FP32 reference instead (_check_attention). Routing agreement is
    pooled over all tokens, since the judge also accepts flips at near-ties."""
    gen = torch.Generator(device=device).manual_seed(80)
    attn_plans, state["attn_plans"] = state["attn_plans"], {}
    same = total = 0
    try:
        for batch, length, sliding in ((1, 1, True), (4, 8, False), (16, 1, True), (32, 8, True)):
            data = _layer_inputs(batch, 3000, length, sliding, device, gen)
            twin = dict(data, k_cache=data["k_cache"].clone(), v_cache=data["v_cache"].clone())
            a_in, s_in, ids_in = _baseline_layer(twin, state)
            a, s, ids = _layer(data, state)
            stream_in = data["stream"]
            same += int((ids == ids_in).sum())
            total += ids.numel()
            da = _rel(a, a_in)
            ds = _rel(s - stream_in, s_in - stream_in)
            print(f"layer check B{batch} L{length}: next input {da:.2e}, stream update {ds:.2e},"
                  f" ids {float((ids == ids_in).float().mean()):.3f}")
            if not (da < 3e-2 and ds < 3e-2):
                return False
    finally:
        state["attn_plans"] = attn_plans
    print(f"layer check: {same}/{total} expert ids identical")
    return same >= 0.95 * total


def prepare(weights: Weights):
    t0 = time.time()
    state = _baseline_prepare(weights)
    bank = state["bank"]
    state["moe"] = {"bank": dict(bank, count=LOCAL_EXPERTS), "workspace": bank["workspace"],
                    "norm_w": state["post_expert_w"]}
    state["proj_plans"], state["attn_plans"], state["moe_plans"] = {}, {}, {}
    device = weights["qkv_gate"].device
    bench = _Bench(device)
    for tune in (_tune_attention, _tune_moe, _tune_proj):
        try:
            tune(state, bench, t0)
        except Exception as e:  # keep SGLang's parts for whatever didn't tune
            print(f"{tune.__name__} failed: {type(e).__name__}: {str(e)[:200]}")
    del bench
    try:
        ok = _check_layer(state, device)
    except Exception as e:
        print(f"layer check failed: {type(e).__name__}: {str(e)[:200]}")
        ok = False
    if not ok:
        print("falling back to SGLang's layer")
        state["proj_plans"], state["attn_plans"], state["moe_plans"] = {}, {}, {}
    torch.cuda.synchronize()
    print(f"prepare: {time.time() - t0:.0f} s")
    return state
